#include <iostream>
#include <memory>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    int total = 0;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        total += x;
    }

    unique_ptr<int> a = make_unique<int>(total);
    unique_ptr<int> b = move(a);

    cout << *b << endl;
    cout << (a == nullptr ? "空手" : "还拿着") << endl;
    return 0;
}

