using namespace std;

int main() {
    int v = 0;
    cin >> v;

    shared_ptr<int> a = make_shared<int>(v);
    cout << a.use_count() << endl;
    {
        shared_ptr<int> b = a;
        cout << a.use_count() << endl;
    }
    cout << a.use_count() << endl;
    cout << *a << endl;
    return 0;
}

